import{_ as e}from"./chunks/Ollama-密钥.BwN44ViN.js";import{_ as t}from"./chunks/通义千问-聊天模型-私有.CuBIdYkO.js";import{_ as r,o,c as i,a2 as s}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/assets/%E9%80%9A%E4%B9%89%E5%8D%83%E9%97%AE-%E5%AE%98%E6%96%B9.CcwA9LOO.png",f=JSON.parse('{"title":"【模型接入】通义千问","description":"","frontmatter":{},"headers":[],"relativePath":"ai/tongyi.md","filePath":"ai/tongyi.md","lastUpdated":null}'),n={name:"ai/tongyi.md"};function p(h,a,d,c,g,b){return o(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="【模型接入】通义千问" tabindex="-1">【模型接入】通义千问 <a class="header-anchor" href="#【模型接入】通义千问" aria-label="Permalink to &quot;【模型接入】通义千问&quot;">​</a></h1><p>项目基于 Spring Alibaba AI 的 <a href="https://github.com/alibaba/spring-ai-alibaba" target="_blank" rel="noreferrer"><code>spring-cloud-alibaba-starters</code></a> ，实现 <a href="https://tongyi.aliyun.com/" target="_blank" rel="noreferrer">通义千问</a> 的接入：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td><a href="https://help.aliyun.com/zh/dashscope/developer-reference/quick-start" target="_blank" rel="noreferrer">通义千问</a></td><td><a href="https://github.com/alibaba/spring-ai-alibaba/blob/main/spring-ai-alibaba-core/src/main/java/com/alibaba/cloud/ai/dashscope/chat/DashScopeChatModel.java" target="_blank" rel="noreferrer">DashScopeChatModel</a></td></tr><tr><td>AI 绘画</td><td><a href="https://help.aliyun.com/zh/dashscope/developer-reference/tongyi-wanxiang/" target="_blank" rel="noreferrer">通义万象</a></td><td><a href="https://github.com/alibaba/spring-ai-alibaba/blob/main/spring-ai-alibaba-core/src/main/java/com/alibaba/cloud/ai/dashscope/image/DashScopeImageModel.java" target="_blank" rel="noreferrer">DashScopeImageModel</a></td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>通义千问有<a href="https://huggingface.co/Qwen" target="_blank" rel="noreferrer">开源版本</a> ，提供包括 0.6B、1.7B、4B、8B、14B、32B 等稠密模型，以及 30B-A3B、235B-A22B、480B-A35B 等 MoE/代码模型，所以我们可以私有化部署。</p><p>当然，能力更强的模型，就需要使用阿里云提供的<a href="https://help.aliyun.com/document_detail/2712816.html?spm=a2c4g.2786271.0.0.4e337211cCVTAk" target="_blank" rel="noreferrer">大模型服务</a> 。</p><p>下面，我们来看看这两种方式怎么申请（部署）？</p><p>友情提示：</p><p>一般情况下，建议先采用“方式一：申请阿里云密钥”，因为阿里云提供了一定的免费额度，具体可以看 <a href="https://dashscope.console.aliyun.com/billing" target="_blank" rel="noreferrer">阿里云计费管理（需要登录）</a> ，搜“免费额度”或者“限时免费”关键字。</p><h3 id="_1-1-方式一-申请阿里云密钥" tabindex="-1">1.1 方式一：申请阿里云密钥 <a class="header-anchor" href="#_1-1-方式一-申请阿里云密钥" aria-label="Permalink to &quot;1.1 方式一：申请阿里云密钥&quot;">​</a></h3><p>参考 <a href="https://help.aliyun.com/zh/dashscope/developer-reference/quick-start" target="_blank" rel="noreferrer">《阿里云大模型 —— 快速模型》</a> 文档，重点是“开通 DashScope 并<a href="https://help.aliyun.com/zh/dashscope/developer-reference/activate-dashscope-and-create-an-api-key" target="_blank" rel="noreferrer">创建 API-KEY</a> ”部分，其它都不用关注。一般 1-2 分钟就可以申请完成！</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，不需要填写“自定义 API URL”（因为 Spring AI 默认官方地址）。如下图所示：</p><p><img src="'+l+'" alt="官方的密钥配置"></p><h3 id="_1-2-方式二-私有化部署" tabindex="-1">1.2 方式二：私有化部署 <a class="header-anchor" href="#_1-2-方式二-私有化部署" aria-label="Permalink to &quot;1.2 方式二：私有化部署&quot;">​</a></h3><p>① 访问 <a href="https://ollama.ai/download" target="_blank" rel="noreferrer">https://ollama.ai/download</a>，下载对应系统 Ollama 客户端，然后安装。</p><p>② 安装完成后，在命令中执行 <code>ollama run qwen2.5</code> 命令，一键部署 <a href="https://ollama.com/library/qwen" target="_blank" rel="noreferrer">通义千问开源模型</a> ，默认跑的是 <code>qwen:7b</code> 模型。</p><hr><p>部署完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。需要填写“密钥” + “自定义 API URL”（因为让 Spring AI 使用该地址）。如下图所示：</p><p><img src="'+e+'" alt="私有的密钥配置"></p><p>注意：使用该方式时，后续配置模型名时，需要使用 <code>qwen2.5</code> ！！！例如说：</p><p><img src="'+t+`" alt="私有的聊天模型"></p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><p>友情提示：</p><p>目前 <code>ai_model</code> 表中，已经预置了一些模型，可以直接使用！！！</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型。</p><p>模型有：<code>qwen3.7-max</code>、<code>qwen3.7-plus</code> 等等，可通过 <a href="https://dashscope.console.aliyun.com/billing" target="_blank" rel="noreferrer">阿里云计费管理（需要登录）</a> 查看。</p><p>每个模型标识的 <code>max_tokens</code>（回复数 Token 数）是不同的，整理表格如下：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>qwen3.7-max</code></td><td>65536</td></tr><tr><td><code>qwen3.7-plus</code></td><td>65536</td></tr></tbody></table><h3 id="_2-2-ai-绘图" tabindex="-1">2.2 AI 绘图 <a class="header-anchor" href="#_2-2-ai-绘图" aria-label="Permalink to &quot;2.2 AI 绘图&quot;">​</a></h3><p>使用 <a href="./image">《AI 绘图》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的图像模型。</p><p>模型有：<code>wanx-v1</code>、<code>wanx-sketch-to-image-v1</code> 等等。</p><p>注意，如果生成图片报错时，可以看看是不是图片尺寸不对，例如说它可能只支持 1024x1024、1024x768、768x1024、768x1152 等尺寸，可见 <a href="https://t.zsxq.com/gNRTG" target="_blank" rel="noreferrer">https://t.zsxq.com/gNRTG</a> 或 <a href="https://t.zsxq.com/1aUhJ" target="_blank" rel="noreferrer">https://t.zsxq.com/1aUhJ</a> 帖子。</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 TongYiChatModel、TongYiImageModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>spring.ai.dashscope.</code> 配置项，替换成你的！</p><p>ps：暂时不支持“方式二：私有化部署”。（后续会支持！）</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    dashscope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 通义千问</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${DASHSCOPE_API_KEY}</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 或 <code>#getImageModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，TongYiChatModelTests、TongYiImagesModelTest 里有对应的测试用例，可以参考。</p>`,42)])])}const u=r(n,[["render",p]]);export{f as __pageData,u as default};
